function recover(S) {
  let stack = [];
  let i = 0;
  while (i < S.length) {
    let depth = 0;
    while (S[i] === '-') { depth++; i++; }
    let val = 0;
    while (i < S.length && S[i] !== '-') { val = val * 10 + parseInt(S[i++]); }
    let node = {val, left: null, right: null};
    while (stack.length > depth) stack.pop();
    if (stack.length > 0) {
      if (!stack[stack.length - 1].left) stack[stack.length - 1].left = node;
      else stack[stack.length - 1].right = node;
    }
    stack.push(node);
  }
  return stack[0];
}
